function applyRules(subtotal, rules) {
  let running = subtotal;
  for (const rule of rules) {
    running = rule(running);
  }
  return running;
}

function volumeRule(total) {
  return total > 500 ? total - total / 10 : total;
}

function couponRule(amount) {
  return (total) => Math.max(0, total - amount);
}

function vipRule(isVip) {
  return (total) => (isVip ? total - total / 20 : total);
}

function priceWithRules(subtotal, rules, taxRate) {
  let running = subtotal;
  for (const rule of rules) {
    running = rule(running);
  }
  const total = running + running * taxRate;
  return Math.round(total * 100) / 100;
}

function runningTotals(subtotal, rules) {
  const totals = [subtotal];
  let running = subtotal;
  for (const rule of rules) {
    running = rule(running);
    totals.push(running);
  }
  return totals;
}

function reverseOrderTotal(subtotal, rules) {
  let running = subtotal;
  for (let i = rules.length - 1; i >= 0; i--) {
    running = rules[i](running);
  }
  return running;
}
